// ═══ CONCILIAÇÃO DE DESPESAS — saídas do extrato × despesas lançadas ═══
// 1) Saída do banco que já tem despesa lançada (mesmo valor, data próxima) → marca a despesa como paga.
// 2) Saída do banco SEM despesa lançada → aparece para você lançar com 1 clique.
// Ficam de fora: repasses a profissionais, transferências internas (InfinitePay ⇄ Santander)
// e pagamento de fatura de cartão (as compras entram pela importação da fatura).
const CONC_CATS=['Aluguel / Condomínio','Utilidades','Impostos e Taxas','Pessoal','Serviços Terceirizados','Equipamentos','Empréstimo / Financiamento','Manutenção e Limpeza','Reforma','Cartão Crédito Empresa','Cartão Crédito Pessoal','Marketing','Consumo','Outras Despesas'];
const CONC_INTERNO=/centro integrado|cinpsi|infinitepay|cloudwalk|resgate|aplica[cç][aã]o|mesma titularidade|transfer[eê]ncia entre contas/i;
const CONC_FATURA=/pagamento cartao|pagto cartao|pagamento de fatura|fatura cart|cartao credito/i;
const CONC_REPASSE=/(pix|transfer[eê]ncia|ted|doc)[^a-z]*(enviad[oa]|para)?.*\b(tatiane|adriana|luciana|mayara|erika|leticia|letícia|priscila|nayra|juliana)\b/i;
const CONC_IGN_KEY='cinpsi_conc_ignorar';
function concIgnLoad(){ const v=load(CONC_IGN_KEY); return Array.isArray(v)?v:[]; }
function concDias(a,b){ return Math.abs((new Date(a+'T12:00:00')-new Date(b+'T12:00:00'))/864e5); }
function concTokD(s){ return planNorm(s).replace(/[^a-z ]/g,' ').split(/\s+/).filter(w=>w.length>2&&!/^(de|da|do|dos|das|pix|enviado|enviada|pagamento|pagto|boleto|compra|cartao|debito|credito|outros|bancos|ltda|eireli|me|sa|conta|ref|referente|parcela)$/.test(w)); }
function concChaveIgn(desc){ return concTokD(desc).slice(0,3).join(' '); }

function concDespPropor(){
  const fx=fluxoLoad().filter(m=>m.tipo==='saida'&&m.valor>0&&!m.conc);
  const desps=finLoad(FK.DESP);
  const ign=concIgnLoad();
  const usados=new Set(desps.filter(d=>d.concFx).map(d=>d.id));
  const ex={interno:0,fatura:0,repasse:0,regra:0};
  const cand=[];
  fx.forEach(m=>{
    const d=m.desc||'';
    if(CONC_INTERNO.test(d)){ ex.interno++; return; }
    if(CONC_FATURA.test(d)){ ex.fatura++; return; }
    if(CONC_REPASSE.test(d)){ ex.repasse++; return; }
    const ch=concChaveIgn(d);
    if(ch&&ign.includes(ch)){ ex.regra++; return; }
    cand.push(m);
  });
  cand.sort((a,b)=>a.data.localeCompare(b.data));

  // Índice de categorias já usadas por descrição parecida (aprende com o histórico)
  const hist=desps.filter(d=>d.cat&&d.desc).map(d=>({t:new Set(concTokD(d.desc)),cat:d.cat}));
  const sugCat=desc=>{
    const t=concTokD(desc); if(!t.length) return 'Outras Despesas';
    const votos={};
    hist.forEach(h=>{ const c=t.filter(w=>h.t.has(w)).length; if(c) votos[h.cat]=(votos[h.cat]||0)+c; });
    const top=Object.entries(votos).sort((a,b)=>b[1]-a[1])[0];
    return top?top[0]:'Outras Despesas';
  };

  const casadas=[], novas=[];
  const cents=v=>Math.round(v*100);
  cand.forEach(m=>{
    const tm=new Set(concTokD(m.desc));
    let melhor=null;
    desps.forEach(d=>{
      if(usados.has(d.id)||d.concFx) return;
      if(cents(d.valor)!==cents(m.valor)) return;
      const dd=concDias(m.data,d.vencimento||d.data);
      if(dd>10) return;
      const nome=concTokD(d.desc).filter(w=>tm.has(w)).length;
      const score=(nome?100:0)+(10-dd);
      if(!melhor||score>melhor.score) melhor={d,dd,nome,score};
    });
    if(melhor){
      usados.add(melhor.d.id);
      casadas.push({m,d:melhor.d,conf:(melhor.nome||melhor.dd<=3)?'alta':'média'});
    } else {
      novas.push({m,cat:sugCat(m.desc)});
    }
  });
  return {casadas,novas,ex,total:cand.length};
}

function concDespAbrir(silencioso){
  const r=concDespPropor();
  window._concD=r;
  if(!r.casadas.length&&!r.novas.length){
    if(!silencioso) toast('Tudo em dia: nenhuma saída do extrato sem conciliar.');
    return;
  }
  document.getElementById('modal-conc')?.remove();
  const catSel=(i,cat)=>`<select class="form-select" style="font-size:11.5px;padding:3px 6px" id="cd-cat-${i}">${CONC_CATS.map(c=>`<option ${c===cat?'selected':''}>${c}</option>`).join('')}</select>`;
  const lCas=r.casadas.map((p,i)=>`<tr style="border-bottom:1px solid var(--border)">
    <td style="padding:6px 8px"><input type="checkbox" class="cd-cas" data-i="${i}" checked></td>
    <td style="padding:6px 8px;font-size:12px;white-space:nowrap">${finFmtDate(p.m.data)}</td>
    <td style="padding:6px 8px;font-size:12px">${esc(p.m.desc)}</td>
    <td style="padding:6px 8px;text-align:right;font-size:12.5px;font-weight:600;color:var(--red)">${finFmt(p.m.valor)}</td>
    <td style="padding:6px 8px;font-size:12px">${esc(p.d.desc)}<div style="font-size:10.5px;color:var(--text3)">venc. ${finFmtDate(p.d.vencimento||p.d.data)}${p.d.pago?' · já estava paga':''}</div></td>
    <td style="padding:6px 8px;text-align:center"><span style="font-size:11px;background:${p.conf==='alta'?'#D1FAE5':'#FEF3C7'};color:${p.conf==='alta'?'#065F46':'#92400E'};padding:2px 8px;border-radius:20px">${p.conf}</span></td></tr>`).join('');
  const lNov=r.novas.map((p,i)=>`<tr style="border-bottom:1px solid var(--border)" id="cd-nrow-${i}">
    <td style="padding:6px 8px"><input type="checkbox" class="cd-nov" data-i="${i}" checked></td>
    <td style="padding:6px 8px;font-size:12px;white-space:nowrap">${finFmtDate(p.m.data)}</td>
    <td style="padding:6px 8px;font-size:12px"><input class="form-input" style="font-size:12px;padding:3px 6px" id="cd-desc-${i}" value="${esc(p.m.desc)}"></td>
    <td style="padding:6px 8px;text-align:right;font-size:12.5px;font-weight:600;color:var(--red)">${finFmt(p.m.valor)}</td>
    <td style="padding:6px 8px">${catSel(i,p.cat)}</td>
    <td style="padding:6px 8px;text-align:center"><button class="btn-ghost" style="font-size:10.5px;padding:2px 7px" title="Nunca mais mostrar saídas parecidas com esta" onclick="concDespIgnorar(${i})">ignorar sempre</button></td></tr>`).join('');
  const exTxt=[r.ex.repasse&&r.ex.repasse+' repasse'+(r.ex.repasse>1?'s':'')+' a profissionais',r.ex.interno&&r.ex.interno+' transferência'+(r.ex.interno>1?'s':'')+' interna'+(r.ex.interno>1?'s':''),r.ex.fatura&&r.ex.fatura+' pagamento'+(r.ex.fatura>1?'s':'')+' de fatura de cartão',r.ex.regra&&r.ex.regra+' por regra "ignorar sempre"'].filter(Boolean).join(' · ');
  const mo=document.createElement('div');
  mo.className='modal-overlay'; mo.id='modal-conc';
  mo.onclick=e=>{ if(e.target===mo) mo.remove(); };
  mo.innerHTML=`<div class="modal" style="max-width:900px;max-height:90vh;display:flex;flex-direction:column">
    <div class="modal-header"><div class="modal-title">🔗 Conciliação de despesas</div>
      <button class="modal-close" onclick="document.getElementById('modal-conc').remove()">×</button></div>
    <div class="modal-body" style="overflow-y:auto;flex:1;padding:0">
      <div style="padding:10px 16px;background:var(--surface2);border-bottom:1px solid var(--border);font-size:12px;color:var(--text2);line-height:1.6">
        Saídas do extrato comparadas com as despesas lançadas (mesmo valor, data até 10 dias de diferença).
        ${exTxt?`<br><span style="color:var(--text3)">Fora da análise: ${exTxt}.</span>`:''}
      </div>
      ${r.novas.length?`<div style="padding:10px 16px 4px;font-weight:600;font-size:13px">⚠️ Pagas no banco e não lançadas (${r.novas.length})</div>
      <table style="width:100%;border-collapse:collapse"><thead><tr style="background:var(--surface2);font-size:11px;color:var(--text3)"><th style="width:30px"></th><th style="padding:6px 8px;text-align:left">Data</th><th style="padding:6px 8px;text-align:left">Descrição (editável)</th><th style="padding:6px 8px;text-align:right">Valor</th><th style="padding:6px 8px;text-align:left">Categoria</th><th></th></tr></thead><tbody>${lNov}</tbody></table>`:''}
      ${r.casadas.length?`<div style="padding:14px 16px 4px;font-weight:600;font-size:13px">✅ Já lançadas — marcar como pagas (${r.casadas.length})</div>
      <table style="width:100%;border-collapse:collapse"><thead><tr style="background:var(--surface2);font-size:11px;color:var(--text3)"><th style="width:30px"></th><th style="padding:6px 8px;text-align:left">Data</th><th style="padding:6px 8px;text-align:left">Saída no extrato</th><th style="padding:6px 8px;text-align:right">Valor</th><th style="padding:6px 8px;text-align:left">Despesa lançada</th><th style="padding:6px 8px">Confiança</th></tr></thead><tbody>${lCas}</tbody></table>`:''}
    </div>
    <div class="modal-footer"><button class="btn-ghost" onclick="document.getElementById('modal-conc').remove()">Agora não</button>
      <button class="btn-save-purple" onclick="concDespAplicar()">✓ Aplicar selecionadas</button></div>
  </div>`;
  document.body.appendChild(mo);
  setTimeout(()=>mo.classList.add('open'),10);
}

function concDespIgnorar(i){
  const p=window._concD&&window._concD.novas[i]; if(!p) return;
  const ch=concChaveIgn(p.m.desc);
  if(!ch){ toast('Não consegui criar uma regra para esta descrição.'); return; }
  const l=concIgnLoad(); if(!l.includes(ch)){ l.push(ch); store(CONC_IGN_KEY,l); }
  p.ignorada=true;
  const tr=document.getElementById('cd-nrow-'+i); if(tr) tr.remove();
  toast('Saídas como "'+p.m.desc.slice(0,30)+'" não serão mais mostradas.');
}

function concDespAplicar(){
  const r=window._concD; if(!r) return;
  const desps=finLoad(FK.DESP), fx=fluxoLoad();
  let nPagas=0, nNovas=0;
  document.querySelectorAll('.cd-cas').forEach(c=>{
    if(!c.checked) return;
    const p=r.casadas[+c.dataset.i]; if(!p) return;
    const d=desps.find(x=>x.id===p.d.id); if(!d) return;
    d.pago=true; d.dataPagamento=p.m.data; d.concFx=p.m.id;
    const f=fx.find(x=>x.id===p.m.id); if(f) f.conc=[d.id];
    nPagas++;
  });
  document.querySelectorAll('.cd-nov').forEach(c=>{
    if(!c.checked) return;
    const i=+c.dataset.i, p=r.novas[i]; if(!p||p.ignorada) return;
    const desc=(document.getElementById('cd-desc-'+i)?.value||p.m.desc).trim();
    const cat=document.getElementById('cd-cat-'+i)?.value||p.cat;
    const id=Date.now()+i+(Math.random()*100|0);
    desps.push({id,desc,cat,valor:p.m.valor,data:p.m.data,vencimento:p.m.data,dataPagamento:p.m.data,tipo:'unica',grupoId:'g_'+id,parcelaAtual:1,totalParcelas:1,pago:true,importado:true,origemBanco:true,concFx:p.m.id});
    const f=fx.find(x=>x.id===p.m.id); if(f) f.conc=[id];
    nNovas++;
  });
  if(!nPagas&&!nNovas){ toast('Nada selecionado.'); return; }
  finSave(FK.DESP,desps); fluxoSave(fx);
  document.getElementById('modal-conc')?.remove();
  fin_refresh(); if(typeof finRenderFluxoCaixa==='function') finRenderFluxoCaixa();
  toast('✓ '+nPagas+' despesa'+(nPagas!==1?'s':'')+' marcada'+(nPagas!==1?'s':'')+' como paga'+(nPagas!==1?'s':'')+' · '+nNovas+' nova'+(nNovas!==1?'s':'')+' lançada'+(nNovas!==1?'s':'')+'.');
}
